lensid.proposed_api:
// New module glasses3d/arview/src/eyewear/lens-identification.ts. It replaces the decision part of optical-material.ts (classifyAssetMaterials, the WeakSets and the live transmission fallback) and partRoleOf in part-visibility.ts.
import type {Material, Object3D} from 'three';
import type {GLTF} from 'three/addons/loaders/GLTFLoader.js';

export type PartClass = 'lens' | 'frame';
export type LensSignal = 'partRole' | 'part_role_legacy' | 'name_token' | 'transmission' | 'alpha' | 'none';
export type SignalSite = 'node' | 'mesh' | 'material' | 'ancestor_node';
export type LensWarningCode = 'role_conflict' | 'unrecognized_partRole' | 'lens_token_excluded' | 'explicit_role_overrides_name'
  | 'last_resort_lens' | 'transmissive_untagged_as_frame' | 'transmissive_frame' | 'material_shared_lens_and_frame'
  | 'no_lens_material' | 'lens_behind_front' | 'region_conflict' | 'lens_appearance_on_frame';
export interface LensWarning {readonly code: LensWarningCode; readonly severity: 'info' | 'warn' | 'error';
  readonly material?: number | null; readonly node?: number; readonly message: string}

/** Everything the rule reads for ONE use (node x primitive) of a material. Built from gltf.parser.json, never from three's merged userData. */
export interface UseSignals {
  readonly materialName: string; readonly nodeName: string;
  readonly nodeExtras: Readonly<Record<string, unknown>> | null;   // nodes[j].extras
  readonly meshExtras: Readonly<Record<string, unknown>> | null;   // meshes[m].extras
  readonly materialExtras: Readonly<Record<string, unknown>> | null; // materials[i].extras
  readonly ancestorExtras: readonly Readonly<Record<string, unknown>>[]; // mesh-less parent nodes, nearest first, scene root excluded
  readonly transmission: number;   // KHR_materials_transmission factor (texture-only counts as >0); 0 if absent
  readonly alpha: number;          // baseColorFactor[3]; 1 if absent
  readonly alphaMode: 'OPAQUE' | 'MASK' | 'BLEND';
}
export interface UseDecision {readonly class: PartClass; readonly signal: LensSignal; readonly site: SignalSite | null;
  readonly value: string | number | null; readonly warnings: readonly LensWarning[]}

/** Pure, three-free, deterministic. The rule order lives only here. */
export function decideUse(s: UseSignals, allowLastResort: boolean): UseDecision;
/** Whole-word tokens: split lower->Upper camelCase, then on every non-letter; lowercase.
 *  'AmberGradientLenses' -> [amber, gradient, lenses]; 'Champagne lens.001' -> [champagne, lens]; 'Eyeglasses' -> [eyeglasses]. */
export function nameTokens(name: string): string[];
export const LENS_TOKENS: ReadonlySet<string>;   // {'lens','lenses','glass'}; 'glasses' deliberately absent
export const NAME_EXCLUSION: RegExp;             // /^(etch|letter|inscri|print)/ per token: etch(ed|ing), lettering, inscription, print(ed)

export interface LensIdentification {
  readonly materials: readonly MaterialLensEntry[];   // see report_entry_shape; one per used glTF material (+ default)
  readonly warnings: readonly LensWarning[];
  readonly lensMaterialCount: number; readonly lastResortUsed: boolean;
  readonly components: {readonly pass: boolean; readonly reasons: readonly string[]};  // the §2 'Components' row
  classOf(material: Material): PartClass | 'mixed' | undefined;
  toReport(): LensIdentificationReport;               // JSON-safe block for report.json
}
/** Classify every material of a parsed GLB. Reads gltf.parser.json and gltf.parser.associations (material->{materials},
 *  primitive Mesh->{meshes,primitives}, node->{nodes}). Never mutates. Synthetic scenes for unit tests may pass
 *  {scene, parser: undefined}: userData is then read as node+mesh extras and material.userData as material extras. */
export function identifyLensMaterials(gltf: Pick<GLTF, 'scene'> & {parser?: GLTF['parser']}): LensIdentification;
/** Fill the class registry, then apply the fallbacks. A 'mixed' material is split into one instance per class
 *  (the existing clone mechanics, optical-material.ts:117-134); the front/arm structural split stays a separate later
 *  step. Idempotent. continuity's second parse calls identify+apply on its own objects. */
export function applyLensIdentification(root: Object3D, id: LensIdentification): void;

// Registry replacing frameMaterials/lensMaterials and the live transmission rule. Call sites keep their names.
export function materialClassOf(material: Material): PartClass | undefined;
export function isOpticalMaterial(material: Material): boolean;          // materialClassOf(m) === 'lens' (unregistered -> false + one dev warning)
export function isFrameMaterial(material: Material): boolean;            // === 'frame'
export function isTranslucentFrameMaterial(material: Material): boolean; // frame && MeshPhysicalMaterial && transmission > 0 (frame stays frame if edited to 0)
export function registerDerivedMaterial(derived: Material, source: Material): void; // replaces markFrameMaterial; also covers lens clones, twins, overlays, canonical replacements

/* decideUse order:
 1. Explicit role. Sites are read in the order node -> mesh -> material -> ancestor_node. node -> mesh matches GLTFLoader's
    effective precedence for single-primitive nodes today. The first site with a usable value decides; a different class
    at any other site adds role_conflict.
    partRole === 'lens' -> lens. partRole in {'frame','temple'} -> frame. Any other partRole string -> unrecognized_partRole, ignored.
    part_role (legacy) matching /^lens/i -> lens. Any other non-empty part_role -> frame (an explicit non-lens assertion,
    e.g. 'hardware', 'temple_left').
    A lens role whose names carry an exclusion token, or a frame role whose names carry a lens token -> explicit_role_overrides_name (info).
 2. Name token. tokens(materialName) and tokens(nodeName) hit LENS_TOKENS -> lens, site = 'material' or 'node' (material first),
    unless any token of either name matches NAME_EXCLUSION -> lens_token_excluded (info), and continue to step 3.
 3. Only when allowLastResort: transmission > 0 -> lens/'transmission'; else alphaMode === 'BLEND' && alpha < 1 -> lens/'alpha'.
    Both add last_resort_lens (warn).
 4. Otherwise frame/'none'. If the material transmits or blends: transmissive_untagged_as_frame (warn) when the last resort
    was barred, transmissive_frame (info) when step 1 made it frame.

identifyLensMaterials:
 (a) Enumerate uses from JSON: every scene node with a mesh, x every primitive -> material index or 'default'.
 (b) Pass 1: decideUse(s, false) for every use.
 (c) If no use is lens, pass 2: decideUse(s, true) over the undecided uses.
     The last resort is asset-level on purpose. Studio GLBs ship transmissive frame parts (FT1119 'Clear pads.001' T 0.96;
     r9 'Crystal acetate' T 1). Per material, any missing role would turn those parts into lenses.
 (d) Material class = the class all its uses agree on. Disagreement -> 'mixed', components.pass=false,
     material_shared_lens_and_frame (error), runtime fallback = split.
 (e) lensMaterialCount === 0 -> components.pass=false, no_lens_material (error, a real defect that is never hidden;
     downstream geometry falls back per WP1.2).
 (f) Checks that only warn and never reclassify: more than 25% of lens-class triangle area at z < -0.03 m -> lens_behind_front
     (this catches crystal temples taken by the last resort); LENSES_part_visibility region disagreeing with the class ->
     region_conflict, profile ignored; LENSES_lens_appearance on a frame-class material -> lens_appearance_on_frame.

Repoint: part-visibility.ts:63-66, optical-material.ts:52/:85-89, lens-material.ts:45 and effective-optical-topology.ts:342
 read materialClassOf / the per-mesh resolved role instead of raw userData.partRole. renderer.lensMeshes = meshes with a
 lens-class material, taken from the same identification and exposed read-only for capture and portrait.

Expected results on the proof set:
 - FT1119 q001: 1 lens material (mat 3 'Champagne lens.001', partRole @node); mat 4 'Clear pads.001' = frame + transmissive_frame.
 - Prada delivery: lens = mat 2 and mat 3 ('Lens | subtle etched lettering.001', partRole lens, explicit_role_overrides_name).
 - r9: lens = mat 3 'Warm brown optical tint' (part_role_legacy 'lens_left'); mat 0 'Crystal acetate' = frame
   (part_role 'frame'/'temple_*') + transmissive_frame; mat 2 'Subtle warm lens inscription' = frame (part_role 'hardware').
 - Shipped amber-horizon / tom-ford-clear: lens by name_token on the material; no last resort. */

lensid.report_entry_shape:
// report.json gets a "lens_identification" block. Each entry in it is one glTF material.
interface MaterialLensEntry {
  index: number | null;                 // glTF materials[] index; null = glTF default material
  name: string;                         // materials[i].name as authored (not three's sanitized name)
  class: 'lens' | 'frame' | 'mixed';    // 'mixed' = used by lens AND frame uses (fails the §2 Components row)
  signal: 'partRole' | 'part_role_legacy' | 'name_token' | 'transmission' | 'alpha' | 'none';  // the step that decided
  site: 'node' | 'mesh' | 'material' | 'ancestor_node' | null;  // where the deciding value was found
  value: string | number | null;        // e.g. 'lens', 'lens_left', 'lenses', 0.96
  uses: {node: number; node_name: string; mesh: number; primitive: number; triangles: number;
         class: 'lens' | 'frame'; signal: string; site: string | null}[];
  evidence: {
    partRole: {site: string; index: number; value: string}[];   // every partRole seen on node/mesh/material/ancestor
    part_role: {site: string; index: number; value: string}[];  // legacy key
    name_tokens: {material: string[]; nodes: Record<string, string[]>; lens_hits: string[]; exclusion_hits: string[]};
    transmission: number; alpha: number; alpha_mode: 'OPAQUE' | 'MASK' | 'BLEND';
    part_visibility_regions: string[];  // LENSES_part_visibility on using nodes (corroboration only)
    lens_appearance_extension: boolean; // corroboration only
    lens_rear_z_m?: number;             // lens/mixed only: min z of its triangles (feeds lens_behind_front)
  };
  warnings: string[];                   // warning codes attached to this material
}
interface LensIdentificationReport {
  rule_version: 'lens-id-v1';
  order: ['partRole|part_role(lens*)', 'name_token(lens|lenses|glass; excl etch|letter|inscri|print)', 'transmission|alpha (asset-level last resort)'];
  last_resort_used: boolean;
  lens_material_count: number; frame_material_count: number; mixed_material_count: number;
  decided_by: {partRole: number; part_role_legacy: number; name_token: number; transmission: number; alpha: number; none: number};
  components: {pass: boolean; reasons: string[]};   // the §2 'Components' row verdict; feeds validate_spec and arview acceptance
  materials: MaterialLensEntry[];
  warnings: {code: string; severity: 'info' | 'warn' | 'error'; material?: number | null; node?: number; message: string}[];
}

